ALTER TABLE Cliente ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE Profissional ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE Procedimento ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE Sala ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE Equipamento ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE Pacote ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE ProfissionalProcedimento ADD ativo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE Produto ADD ativo BOOLEAN NOT NULL DEFAULT TRUE, ADD estoque_minimo DECIMAL(12,3) NOT NULL DEFAULT 0;
ALTER TABLE Anamnese ADD contraindicacoes TEXT, ADD id_autor INT UNSIGNED NULL;
ALTER TABLE Atendimento ADD status ENUM('iniciado','concluido') NOT NULL DEFAULT 'concluido', ADD id_autor INT UNSIGNED NULL;
ALTER TABLE Parcela ADD valor_recebido DECIMAL(10,2) NOT NULL DEFAULT 0, ADD CONSTRAINT ck_parcela_recebido CHECK(valor_recebido >= 0 AND valor_recebido <= valor_parcela);
UPDATE Parcela SET valor_recebido=valor_parcela WHERE status='paga';
ALTER TABLE MovimentacaoEstoque ADD motivo VARCHAR(500), ADD id_autor INT UNSIGNED NULL;
CREATE TABLE Auditoria (id_auditoria BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_usuario INT UNSIGNED NULL,acao VARCHAR(80) NOT NULL,recurso VARCHAR(80) NOT NULL,id_registro INT UNSIGNED NULL,data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_audit_data(data));
CREATE TABLE Disponibilidade (id_disponibilidade INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_profissional INT UNSIGNED NOT NULL,dia_semana TINYINT NOT NULL,hora_inicio TIME NOT NULL,hora_fim TIME NOT NULL,ativo BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(id_profissional) REFERENCES Profissional(id_profissional),CHECK(dia_semana BETWEEN 0 AND 6),CHECK(hora_fim>hora_inicio));
CREATE TABLE Bloqueio (id_bloqueio INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_profissional INT UNSIGNED NULL,id_sala INT UNSIGNED NULL,id_equipamento INT UNSIGNED NULL,inicio DATETIME NOT NULL,fim DATETIME NOT NULL,motivo VARCHAR(500) NOT NULL,ativo BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(id_profissional) REFERENCES Profissional(id_profissional),FOREIGN KEY(id_sala) REFERENCES Sala(id_sala),FOREIGN KEY(id_equipamento) REFERENCES Equipamento(id_equipamento),CHECK(fim>inicio),CHECK(id_profissional IS NOT NULL OR id_sala IS NOT NULL OR id_equipamento IS NOT NULL));
CREATE TABLE EventoAgenda (id_evento INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_agendamento INT UNSIGNED NOT NULL,tipo VARCHAR(40) NOT NULL,motivo VARCHAR(500) NOT NULL,id_autor INT UNSIGNED NOT NULL,data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_agendamento) REFERENCES Agendamento(id_agendamento));
CREATE TABLE ConsumoSessao (id_consumo INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_agendamento INT UNSIGNED NOT NULL UNIQUE,id_pacote_cliente INT UNSIGNED NOT NULL,data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_agendamento) REFERENCES Agendamento(id_agendamento),FOREIGN KEY(id_pacote_cliente) REFERENCES PacoteCliente(id_pacote_cliente));
CREATE TABLE Comissao (id_comissao INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_atendimento INT UNSIGNED NOT NULL UNIQUE,id_profissional INT UNSIGNED NOT NULL,base_calculo DECIMAL(10,2) NOT NULL,percentual DECIMAL(5,2) NOT NULL,valor DECIMAL(10,2) NOT NULL,status ENUM('pendente','paga','cancelada') NOT NULL DEFAULT 'pendente',data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,data_pagamento DATETIME NULL,FOREIGN KEY(id_atendimento) REFERENCES Atendimento(id_atendimento),FOREIGN KEY(id_profissional) REFERENCES Profissional(id_profissional));
CREATE TABLE Recebimento (id_recebimento INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_parcela INT UNSIGNED NOT NULL,valor DECIMAL(10,2) NOT NULL,tipo ENUM('recebimento','estorno') NOT NULL,id_autor INT UNSIGNED NOT NULL,data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,motivo VARCHAR(500),FOREIGN KEY(id_parcela) REFERENCES Parcela(id_parcela));
CREATE TABLE HistoricoPreco (id_historico INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_procedimento INT UNSIGNED NOT NULL,valor DECIMAL(10,2) NOT NULL,data DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,id_autor INT UNSIGNED NOT NULL,FOREIGN KEY(id_procedimento) REFERENCES Procedimento(id_procedimento));
